{
  "gate_token": "J3fUORLtRnf09ChVck1fhQ",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unrolls a map of the ruined city at dusk.",
      "visual_description": "A windswept ridge overlooking a shattered skyline of broken spires and torn royal banners; an ink-stained coat flaps in the wind as a brass compass spins.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of three false paths.",
      "visual_description": "A close-up of an oil lamp with a single glowing eye in its flame, casting trembling shadows across Mara's map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts ahead through cracked cobblestones.",
      "visual_description": "A small clockwork fox with a key-wind tail and blue glass eyes trots between fallen statues, leaving tiny brass footprints in ash.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver arrives by stepping out of a shop window.",
      "visual_description": "A figure in a clear diving helmet emerges from a rippling pane of glass, coat reflecting the broken city's neon-pale lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "The team studies the castle gates from a safe alley.",
      "visual_description": "Massive iron gates wrapped in ivy and old royal banners; four silhouettes peek from behind a crumbling archway.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "An armored patrol clanks past in lockstep.",
      "visual_description": "From the alley floor, a low view of armored boots and pikes marching by; Tin Fox crouches frozen, eyes dimmed to hide their glow.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "They stumble upon a sleeping official slumped by the gate.",
      "visual_description": "A round figure snores against a stone wall, ledger book as pillow, stamped papers stuck to his sleeves and one cheek.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp whispers the password into the gate's lock.",
      "visual_description": "The lamp's single flame-eye leans close to an ornate keyhole shaped like a roaring mouth, runes blooming gold around it.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Inside, the cursed tower looms over a black courtyard.",
      "visual_description": "A leaning spire wreathed in violet smoke; cracked flagstones glow faintly under the team's cautious footsteps.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a great beast rumble beneath the stones.",
      "visual_description": "Steam jets up through floor cracks, lighting Mara's worried face; Tin Fox's ears swivel toward a deep tremor below.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver dives through a tall stained-glass window.",
      "visual_description": "A figure in a diving helmet plunges headfirst into a saint-painted window as if it were water, ripples spreading outward in colored light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "On the far side, the captive waits behind a magic door.",
      "visual_description": "A heavy door of floating runes hovers in a candle-lit chamber; through its keyhole-light, a small huddled silhouette is visible.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox's key-wind tail picks the rune lock.",
      "visual_description": "Close-up of tiny brass claws turning a glowing rune; sparks fly as the door's symbols rearrange like falling dominoes.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "Frightened townsfolk press shutters closed as alarms ring.",
      "visual_description": "Narrow lane between leaning houses; shutters slam one after another, faces vanishing as bells clang from the cursed tower.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "The sleeping official tumbles into the team's path, still snoring.",
      "visual_description": "The round figure rolls down a stair, ledger flapping, somehow undisturbed; Mara hops over him while Glass Diver stares in disbelief.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "A patrol corners them at the river bridge.",
      "visual_description": "Armored figures in silhouette block one end of a long stone bridge; torchlight glints off pike-tips and the dark river roils below.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "Oracle Lamp blinds the patrol with a sudden flare.",
      "visual_description": "The lamp's flame-eye bursts into a starburst of white light; armored shapes throw arms over visors as the team sprints past.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge as the ruined city fades behind.",
      "visual_description": "Wide shot at dawn: four small figures crossing a long stone bridge into mist, royal banners burning dim on the far towers behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

